#!/usr/bin/env python3
"""Render benchmark CSVs into README.md and results/summary.md.

Reads results/results_*.csv (written by bench_gpu on the benchmark machine),
formats one markdown table per CSV, and idempotently replaces the region
between the BENCH markers in README.md:

    <!-- BENCH:BEGIN -->  ...generated, do not edit...  <!-- BENCH:END -->

Also writes the same tables to results/summary.md. Stdlib only. Wired to
`make readme-results`.
"""

import argparse
import csv
import glob
import re
import sys
from pathlib import Path

BEGIN = "<!-- BENCH:BEGIN -->"
END = "<!-- BENCH:END -->"

COLUMNS = [
    ("op", "op"),
    ("resolution", "resolution"),
    ("cpu_1t_ms", "cpu 1-thread (ms)"),
    ("omp_ms", "openmp (ms)"),
    ("gpu_kernel_ms", "gpu kernel (ms)"),
    ("gpu_wall_ms", "gpu wall (ms)"),
    ("speedup_vs_1t", "speedup vs 1t"),
    ("speedup_vs_omp", "speedup vs omp"),
]


def fmt_ms(text: str) -> str:
    if not text:
        return "—"
    v = float(text)
    if v >= 100:
        return f"{v:.0f}"
    if v >= 10:
        return f"{v:.1f}"
    if v >= 1:
        return f"{v:.2f}"
    if v >= 0.1:
        return f"{v:.3f}"
    return f"{v:.4f}"


def fmt_speedup(text: str) -> str:
    if not text:
        return "—"
    return f"{float(text):.1f}×"


def render_csv(path: Path) -> str:
    comments = []
    rows = []
    with path.open() as f:
        for line in f:
            line = line.rstrip("\n")
            if line.startswith("#"):
                comments.append(line.lstrip("# "))
            elif line:
                rows.append(line)
    if not rows:
        raise SystemExit(f"error: {path} has no data rows")

    reader = csv.DictReader(rows)
    device = next((c.split(":", 1)[1].strip() for c in comments if c.startswith("device:")),
                  path.stem.replace("results_", "").replace("_", " "))
    meta = "; ".join(c for c in comments if not c.startswith(("device:", "methodology:")))

    out = [f"#### {device}", ""]
    if meta:
        out += [f"*{meta}*", ""]
    out.append("| " + " | ".join(h for _, h in COLUMNS) + " |")
    out.append("|" + "|".join("---" for _ in COLUMNS) + "|")
    has_batch = False
    for r in reader:
        cells = [
            f"`{r['op']}`",
            r["resolution"],
            fmt_ms(r["cpu_1t_ms"]),
            fmt_ms(r["omp_ms"]),
            fmt_ms(r["gpu_kernel_ms"]),
            fmt_ms(r["gpu_wall_ms"]),
            fmt_speedup(r["speedup_vs_1t"]),
            fmt_speedup(r["speedup_vs_omp"]),
        ]
        if r["op"].endswith("_batch100"):
            has_batch = True
            if r["gpu_wall_ms"]:
                cells[0] += f" ({1000.0 / float(r['gpu_wall_ms']):.0f} img/s)"
        out.append("| " + " | ".join(cells) + " |")
    out.append("")
    out.append(
        "*Medians of 100 timed runs after 10 warm-ups. `gpu kernel` = cudaEvent time around "
        "the kernel(s) only; `gpu wall` = std::chrono around upload + kernel + download. "
        "Speedups compare CPU medians against `gpu kernel`.*"
    )
    if has_batch:
        out.append("")
        out.append(
            "*`_batch100` rows are per-image figures over a pipelined 100-image batch "
            "(throughput in parentheses); their CPU columns use 5 timed batch runs.*"
        )
    return "\n".join(out)


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--results-glob", default="results/results_*.csv")
    ap.add_argument("--readme", default="README.md", type=Path)
    ap.add_argument("--summary", default="results/summary.md", type=Path)
    args = ap.parse_args()

    paths = sorted(Path(p) for p in glob.glob(args.results_glob))
    if not paths:
        print(
            f"error: no CSVs match {args.results_glob!r} — run colab/run_t4.sh on a GPU "
            "machine and copy the CSV into results/ first",
            file=sys.stderr,
        )
        return 1

    tables = "\n\n".join(render_csv(p) for p in paths)
    body = (
        f"{BEGIN}\n"
        f"<!-- generated by scripts/render_results.py from "
        f"{', '.join(str(p) for p in paths)} — do not edit by hand -->\n\n"
        f"{tables}\n"
        f"{END}"
    )

    readme = args.readme.read_text()
    if BEGIN not in readme or END not in readme:
        print(f"error: {args.readme} is missing the {BEGIN} / {END} markers", file=sys.stderr)
        return 1
    new_readme = re.sub(
        re.escape(BEGIN) + r".*?" + re.escape(END), lambda _: body, readme, count=1, flags=re.S
    )
    args.readme.write_text(new_readme)

    args.summary.parent.mkdir(parents=True, exist_ok=True)
    args.summary.write_text(
        "# Benchmark summary\n\n"
        "Generated by `scripts/render_results.py` from "
        + ", ".join(f"`{p}`" for p in paths)
        + ".\n\n"
        + tables
        + "\n"
    )

    print(f"updated {args.readme} and {args.summary} from {len(paths)} CSV file(s)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
